/**
 * Pay-stubs handler — read a single stub plus its parent run + employee context.
 *
 * Stubs are generated by `pay-runs/:id/process` and are immutable from the
 * user's POV (printable). Always scoped to the authenticated user's own
 * pay-runs; cross-user reads return 404.
 *
 * @module
 */
import { type Request, type Response, Router } from 'express'

import { getParamId, getUserId } from '@molecule/api-bonds-default-express'
import { findById } from '@molecule/api-database'
import { t } from '@molecule/api-i18n'

const router = Router()

router.get('/:id', async (req: Request, res: Response) => {
  const userId = getUserId(res)
  if (!userId) return res.status(401).json({ error: t('auth.unauthorized') })

  const stubId = getParamId(req)
  const stub = await findById<Record<string, unknown>>('pay_stubs', stubId)
  if (!stub) {
    return res.status(404).json({ error: t('payRuns.notFound') })
  }
  const payRun = await findById<Record<string, unknown>>('pay_runs', String(stub.pay_run_id))
  if (!payRun || payRun.user_id !== userId) {
    return res.status(404).json({ error: t('payRuns.notFound') })
  }

  let employee: Record<string, unknown> | null = null
  if (stub.employee_id) {
    employee = await findById<Record<string, unknown>>('employees', String(stub.employee_id))
  }

  res.json({ stub, payRun, employee })
})

export default router
